<template>
  <nav class="chapter-rail" :aria-label="label">
    <span
      class="chapter-rail-lens"
      :class="{ ready: lensReady }"
      :style="lensStyle"
      aria-hidden="true"
    ></span>
    <button
      v-for="item in items"
      :key="item.id"
      class="chapter-rail-item"
      :class="{ active: item.id === activeId }"
      :data-chapter-id="item.id"
      type="button"
      :title="item.title || item.label"
      :aria-current="item.id === activeId ? 'location' : undefined"
      @click="scrollToChapter(item.id)"
    >
      <span class="chapter-rail-dot" aria-hidden="true"></span>
      <span>{{ item.label }}</span>
    </button>
  </nav>
</template>

<script>
export default {
  name: 'ChapterRail',
  props: {
    items: {
      type: Array,
      required: true
    },
    label: {
      type: String,
      default: 'Page sections'
    }
  },
  data() {
    return {
      activeId: this.items[0] ? this.items[0].id : '',
      frame: null,
      lensReady: false,
      lensStyle: {
        opacity: 0
      }
    };
  },
  watch: {
    items: {
      deep: true,
      handler() {
        this.lensReady = false;
        this.$nextTick(this.updateActive);
      }
    }
  },
  mounted() {
    this.onScroll = () => {
      if (this.frame) return;
      this.frame = requestAnimationFrame(() => {
        this.frame = null;
        this.updateActive();
      });
    };
    window.addEventListener('scroll', this.onScroll, { passive: true });
    window.addEventListener('resize', this.onScroll, { passive: true });
    this.$nextTick(this.updateActive);
    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(() => this.updateLens()).catch(() => {});
    }
  },
  unmounted() {
    window.removeEventListener('scroll', this.onScroll);
    window.removeEventListener('resize', this.onScroll);
    if (this.frame) cancelAnimationFrame(this.frame);
  },
  methods: {
    updateActive() {
      const candidates = this.items
        .map((item) => ({ item, el: document.getElementById(item.id) }))
        .filter(({ el }) => el);
      if (!candidates.length) return;

      const focusLine = Math.min(window.innerHeight * 0.34, 300);
      let current = candidates[0].item.id;
      for (const candidate of candidates) {
        if (candidate.el.getBoundingClientRect().top <= focusLine) {
          current = candidate.item.id;
        }
      }
      if (this.activeId !== current) {
        this.activeId = current;
      }
      this.$nextTick(this.updateLens);
    },
    updateLens() {
      if (!this.$el) return;
      const buttons = Array.from(this.$el.querySelectorAll('.chapter-rail-item'));
      const active = buttons.find((button) => button.dataset.chapterId === this.activeId);
      if (!active) return;

      this.lensStyle = {
        width: `${active.offsetWidth}px`,
        height: `${active.offsetHeight}px`,
        transform: `translate3d(${active.offsetLeft}px, ${active.offsetTop}px, 0)`,
        opacity: 1
      };

      if (!this.lensReady) {
        requestAnimationFrame(() => {
          if (this.$el) this.lensReady = true;
        });
      }
    },
    scrollToChapter(id) {
      const target = document.getElementById(id);
      if (!target) return;
      this.activeId = id;
      this.$nextTick(this.updateLens);
      const reduceMotion = window.matchMedia
        && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      target.scrollIntoView({
        behavior: reduceMotion ? 'auto' : 'smooth',
        block: 'start'
      });
    }
  }
};
</script>

