const RAIL_SELECTOR = 'div.scroll-container';
const MEDIA_SELECTOR = 'img, video';

function centerOffset(rail, item) {
  return item.offsetLeft - (rail.clientWidth - item.offsetWidth) / 2;
}

function makeClone(item, position) {
  const clone = item.cloneNode(true);
  clone.removeAttribute('id');
  clone.removeAttribute('data-media-rail-original');
  clone.setAttribute('data-media-rail-clone', position);
  clone.setAttribute('aria-hidden', 'true');
  clone.setAttribute('tabindex', '-1');
  clone.setAttribute('draggable', 'false');
  clone.classList.remove('scroll-reveal-item', 'scroll-reveal-visible', 'media-rail-active');
  if (clone.matches('video')) {
    clone.removeAttribute('controls');
    clone.muted = true;
    clone.preload = 'metadata';
  }
  return clone;
}

function enhanceRail(rail) {
  if (rail.dataset.mediaRailEnhanced === 'true') return null;

  const originals = Array.from(rail.children)
    .filter((item) => item.matches(MEDIA_SELECTOR)
      && !item.hasAttribute('data-media-rail-clone'));
  if (originals.length < 2) return null;

  rail.dataset.mediaRailEnhanced = 'true';
  rail.classList.add('media-rail-loop');
  originals.forEach((item, index) => {
    item.setAttribute('data-media-rail-original', 'true');
    item.setAttribute('draggable', 'false');
    if (item.matches('img')) {
      item.decoding = 'async';
      item.loading = index < 2 || index === originals.length - 1 ? 'eager' : 'lazy';
    } else {
      item.preload = index === 0 ? 'metadata' : 'none';
    }
  });

  const headClone = makeClone(originals[originals.length - 1], 'head');
  const tailClone = makeClone(originals[0], 'tail');
  rail.insertBefore(headClone, originals[0]);
  rail.appendChild(tailClone);

  const items = [headClone, ...originals, tailClone];
  const initialInlineSnap = rail.style.scrollSnapType;
  const initialInlineBehavior = rail.style.scrollBehavior;
  const supportsScrollEnd = 'onscrollend' in rail;
  let centers = [];
  let activeItem = null;
  let currentOriginal = originals[0];
  let jumping = false;
  let pendingJump = null;
  let interacted = false;
  let scrollTimer = null;
  let resizeFrame = null;
  let visualFrame = null;
  let measureFrame = null;

  const restoreInlineStyle = (property, value) => {
    if (value) rail.style.setProperty(property, value);
    else rail.style.removeProperty(property);
  };

  const measure = () => {
    centers = items.map((item) => item.offsetLeft + item.offsetWidth / 2);
  };

  const nearestItem = () => {
    if (!centers.length) measure();
    const target = rail.scrollLeft + rail.clientWidth / 2;
    let low = 0;
    let high = centers.length - 1;
    while (low < high) {
      const mid = Math.floor((low + high) / 2);
      if (centers[mid] < target) low = mid + 1;
      else high = mid;
    }
    if (low > 0 && Math.abs(centers[low - 1] - target) <= Math.abs(centers[low] - target)) {
      return items[low - 1];
    }
    return items[low];
  };

  const originalFor = (item) => {
    if (item === headClone) return originals[originals.length - 1];
    if (item === tailClone) return originals[0];
    return item;
  };

  const updateActiveVisual = () => {
    visualFrame = null;
    if (!rail.isConnected) return;
    const nextActive = nearestItem();
    if (nextActive !== activeItem) {
      if (activeItem) activeItem.classList.remove('media-rail-active');
      nextActive.classList.add('media-rail-active');
      activeItem = nextActive;
    }
    currentOriginal = originalFor(nextActive);
  };

  const scheduleActiveVisual = () => {
    if (visualFrame) return;
    visualFrame = requestAnimationFrame(updateActiveVisual);
  };

  const jumpTo = (item) => {
    if (!item || !rail.isConnected) return;
    if (jumping) {
      pendingJump = item;
      return;
    }
    jumping = true;
    rail.style.scrollSnapType = 'none';
    rail.style.scrollBehavior = 'auto';
    rail.scrollLeft = centerOffset(rail, item);
    updateActiveVisual();
    requestAnimationFrame(() => {
      restoreInlineStyle('scroll-snap-type', initialInlineSnap);
      restoreInlineStyle('scroll-behavior', initialInlineBehavior);
      jumping = false;
      rail.classList.add('media-rail-ready');
      measure();
      scheduleActiveVisual();
      if (pendingJump) {
        const nextJump = pendingJump;
        pendingJump = null;
        jumpTo(nextJump);
      }
    });
  };

  const settle = () => {
    if (jumping || !rail.isConnected) return;
    updateActiveVisual();
    if (activeItem === headClone) jumpTo(originals[originals.length - 1]);
    else if (activeItem === tailClone) jumpTo(originals[0]);
  };

  const onScroll = () => {
    scheduleActiveVisual();
    if (jumping || supportsScrollEnd || !rail.classList.contains('media-rail-ready')) return;
    window.clearTimeout(scrollTimer);
    scrollTimer = window.setTimeout(settle, 140);
  };

  const markInteracted = () => {
    interacted = true;
  };

  const onResize = () => {
    if (resizeFrame) cancelAnimationFrame(resizeFrame);
    resizeFrame = requestAnimationFrame(() => {
      resizeFrame = null;
      measure();
      if (rail.classList.contains('media-rail-ready')) jumpTo(currentOriginal);
    });
  };

  const onMediaReady = () => {
    if (measureFrame) cancelAnimationFrame(measureFrame);
    measureFrame = requestAnimationFrame(() => {
      measureFrame = null;
      measure();
      if (!interacted) jumpTo(originals[0]);
      else scheduleActiveVisual();
    });
  };

  rail.addEventListener('scroll', onScroll, { passive: true });
  if (supportsScrollEnd) rail.addEventListener('scrollend', settle, { passive: true });
  rail.addEventListener('pointerdown', markInteracted, { passive: true });
  rail.addEventListener('touchstart', markInteracted, { passive: true });
  rail.addEventListener('wheel', markInteracted, { passive: true });
  originals.forEach((item) => {
    const eventName = item.matches('video') ? 'loadedmetadata' : 'load';
    if ((item.matches('img') && !item.complete)
      || (item.matches('video') && item.readyState < 1)) {
      item.addEventListener(eventName, onMediaReady, { once: true });
    }
  });

  const resizeObserver = typeof ResizeObserver !== 'undefined'
    ? new ResizeObserver(onResize)
    : null;
  if (resizeObserver) resizeObserver.observe(rail);

  requestAnimationFrame(() => {
    measure();
    jumpTo(originals[0]);
  });

  return () => {
    window.clearTimeout(scrollTimer);
    if (resizeFrame) cancelAnimationFrame(resizeFrame);
    if (visualFrame) cancelAnimationFrame(visualFrame);
    if (measureFrame) cancelAnimationFrame(measureFrame);
    if (resizeObserver) resizeObserver.disconnect();
    rail.removeEventListener('scroll', onScroll);
    if (supportsScrollEnd) rail.removeEventListener('scrollend', settle);
    rail.removeEventListener('pointerdown', markInteracted);
    rail.removeEventListener('touchstart', markInteracted);
    rail.removeEventListener('wheel', markInteracted);
    originals.forEach((item) => {
      item.removeEventListener(item.matches('video') ? 'loadedmetadata' : 'load', onMediaReady);
      item.removeAttribute('data-media-rail-original');
      item.classList.remove('media-rail-active');
    });
    headClone.remove();
    tailClone.remove();
    rail.classList.remove('media-rail-loop', 'media-rail-ready');
    delete rail.dataset.mediaRailEnhanced;
  };
}

export function initCircularMediaRails(root = document) {
  const controllers = new Map();
  let scanFrame = null;

  const scan = () => {
    scanFrame = null;
    controllers.forEach((cleanup, rail) => {
      if (!rail.isConnected) {
        cleanup();
        controllers.delete(rail);
      }
    });
    root.querySelectorAll(RAIL_SELECTOR).forEach((rail) => {
      if (controllers.has(rail)) return;
      const cleanup = enhanceRail(rail);
      if (cleanup) controllers.set(rail, cleanup);
    });
  };

  const scheduleScan = () => {
    if (scanFrame) return;
    scanFrame = requestAnimationFrame(scan);
  };

  const observer = new MutationObserver(scheduleScan);
  observer.observe(root, { childList: true, subtree: true });
  scheduleScan();

  return () => {
    observer.disconnect();
    if (scanFrame) cancelAnimationFrame(scanFrame);
    controllers.forEach((cleanup) => cleanup());
    controllers.clear();
  };
}
